def max_sum_rectangular_grid(grid, n):
    """Write a function to find out the maximum sum such that no two chosen numbers are adjacent for the given rectangular grid of dimension 2 x n.

    No two chosen numbers may be adjacent horizontally, vertically, or
    diagonally. Therefore at most one number can be chosen from any column,
    and numbers cannot be chosen from consecutive columns. Each column can
    consequently be represented by its larger value, reducing the problem
    to finding the maximum sum of non-adjacent column values. Choosing no
    numbers is allowed, so the result is never negative.
    """
    if not grid:
        return 0
    if n is None:
        limit = min(len(row) for row in grid)
    elif n <= 0:
        return 0
    else:
        limit = min(n, min(len(row) for row in grid))

    incl = 0
    excl = 0
    for col in range(limit):
        column_max = max(row[col] for row in grid)
        incl, excl = excl + column_max, max(incl, excl)
    return max(incl, excl)
